export function searchLocal(q) {
  const lower = q.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
  return DB.filter(m => {
    const fields = [m.title, m.original_title, m.director, ...(m.genres || []), ...(m.cast || [])].join(" ").toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
    return lower.split(/\s+/).every(word => fields.includes(word));
  }).slice(0, 12);
}
